fn shell_game(n: i32, x: i8) -> i8 {
    // Period is 6, so we only need to simulate up to 5 moves.
    let mut pos = x;
    let k = (n % 6) as i32;

    for i in 1..=k {
        if i % 2 == 1 {
            // odd: swap 0 <-> 1
            pos = match pos {
                0 => 1,
                1 => 0,
                _ => pos, // 2 stays
            };
        } else {
            // even: swap 1 <-> 2
            pos = match pos {
                1 => 2,
                2 => 1,
                _ => pos, // 0 stays
            };
        }
    }

    pos
}